\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── IPCC Climate Theme ──
\definecolor{primary}{HTML}{1E3A5F}      % deep navy
\definecolor{secondary}{HTML}{D97706}    % amber
\definecolor{accent}{HTML}{DC2626}       % vermilion/red
\definecolor{bgposter}{HTML}{F1F5F9}     % cool slate background
\definecolor{redbg}{HTML}{FEF2F2}        % warm red tint
\definecolor{bluebg}{HTML}{EFF6FF}       % cool blue tint
\definecolor{darkbg}{HTML}{F0FDF4}      % green tint for solutions
\definecolor{yellowbg}{HTML}{FFFBEB}    % warm amber tint
\definecolor{redtitlebg}{HTML}{FEE2E2}
\definecolor{bluetitlebg}{HTML}{DBEAFE}
\definecolor{darktitlebg}{HTML}{DCFCE7}
\definecolor{yellowtitlebg}{HTML}{FEF3C7}
\definecolor{textdark}{HTML}{1F2937}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{FFEDD5}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=4pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}\textbullet}}
\setlist[enumerate]{leftmargin=20pt, itemsep=4pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=redtitlebg,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=bluetitlebg,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=yellowbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=yellowtitlebg,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{059669},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{059669},
    coltitle=059669, colbacktitle=darktitlebg,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=2pt, titlerule style={059669!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=accent!18!white,
    borderline west={6pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=accent,
    toptitle=4pt, bottomtitle=4pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{76}{92}\selectfont\bfseries Climate Change 2023}\\[10pt]
  {\fontsize{42}{52}\selectfont\bfseries IPCC AR6 Synthesis Report Key Findings}\\[8pt]
  {\fontsize{30}{38}\selectfont\color{white!80} Intergovernmental Panel on Climate Change | 2023}
}

% ══ STATS BANNER — 7 Headline Metrics ══
\posterbox[
  enhanced, colback=primary!10!white, boxrule=0pt, arc=0pt,
  left=8pt, right=8pt, top=4pt, bottom=4pt,
  valign=center, borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \fcolorbox{secondary!40}{stathighlight}{\parbox{0.125\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{54}{66}\selectfont\bfseries\color{primary}1.1°C}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textdark}Temp. Rise}\vspace{4pt}%
  }}\hfill
  \fcolorbox{secondary!40}{stathighlight}{\parbox{0.125\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{54}{66}\selectfont\bfseries\color{primary}410}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textdark}CO₂ ppm}\vspace{4pt}%
  }}\hfill
  \fcolorbox{secondary!40}{stathighlight}{\parbox{0.125\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{54}{66}\selectfont\bfseries\color{primary}59}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textdark}GtCO₂e/yr}\vspace{4pt}%
  }}\hfill
  \fcolorbox{accent!40}{stathighlight}{\parbox{0.125\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{54}{66}\selectfont\bfseries\color{accent}~500}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textdark}GtCO₂ Budget}\vspace{4pt}%
  }}\hfill
  \fcolorbox{accent!40}{stathighlight}{\parbox{0.125\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{54}{66}\selectfont\bfseries\color{accent}43\%}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textdark}Cut by 2030}\vspace{4pt}%
  }}\hfill
  \fcolorbox{secondary!40}{stathighlight}{\parbox{0.125\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{54}{66}\selectfont\bfseries\color{primary}~0.20m}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textdark}Sea Level}\vspace{4pt}%
  }}\hfill
  \fcolorbox{accent!40}{stathighlight}{\parbox{0.125\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{54}{66}\selectfont\bfseries\color{accent}3.3–3.6B}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textdark}People at Risk}\vspace{4pt}%
  }}
}

% ══ ROW A: Observed Changes | Future Projections | Risks ══
\posterbox[redcard, title={Observed Changes and Current State}
]{name=observed, column=1, between=row6 and row11}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item Global surface temp. rose +1.1°C (2011–2020 vs. 1850–1900)
    \item Atmospheric CO₂ reached 410 ppm — highest in 2 million years
    \item GHG emissions: ~59 GtCO₂e in 2019 from fossil fuels \& land use
    \item Arctic sea ice declined ~40\% (September minimum, 1979–2020)
    \item Sea level rose ~0.20 m since 1901
  \end{itemize}
  \vspace{4pt}
  \colorbox{redbg!50}{\parbox{0.92\linewidth}{%
    \fontsize{24}{32}\selectfont
    \textbf{Every region} experiencing increased frequency \& intensity of heatwaves, heavy precipitation, droughts, and tropical cyclones.}}
}

\posterbox[ambercard, title={Future Projections — SSP Scenarios}
]{name=projections, column=2, between=row6 and row11}{
  \fontsize{28}{36}\selectfont
  \centering
  \begin{tabular}{lcl}
    \rowcolor{secondary!15}
    \textbf{Scenario} & \textbf{Warming} & \textbf{Description} \\
    SSP1-1.9 & \textbf{~1.4°C} & Very low emissions \\
    SSP1-2.6 & ~1.8°C & Low emissions \\
    SSP2-4.5 & ~2.7°C & Intermediate \\
    SSP3-7.0 & ~3.6°C & High emissions \\
    SSP5-8.5 & \color{accent}\bfseries~4.4°C & Very high emissions \\
  \end{tabular}
  \vspace{6pt}
  \colorbox{yellowbg!60}{\parbox{0.92\linewidth}{%
    \fontsize{24}{32}\selectfont Sea level rise: 0.28–0.55m (SSP1-1.9) to 0.63–1.01m (SSP5-8.5) by 2100.}}
}

\posterbox[redcard, title={Risks, Vulnerabilities \& Impacts}
]{name=risks, column=3, between=row6 and row11}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item \textbf{3.3–3.6 billion} people in contexts highly vulnerable to climate change
    \item Climate hazards compound poverty, inequality, ecosystem degradation
    \item Up to 14\% of terrestrial species at very high extinction risk at 1.5°C
  \end{itemize}
  \vspace{4pt}
  \colorbox{redbg!50}{\parbox{0.92\linewidth}{%
    \fontsize{24}{32}\selectfont
    \textbf{Food security}: crop yield growth slowing; fisheries declining in tropics.\\
    \textbf{Water stress}: >50\% of population faces severe scarcity >1 month/yr.}}
}

% ══ ROW B: Mitigation Pathways | Urgency ══
\posterbox[darkcard, title={Mitigation Pathways}
]{name=mitigation, column=1, between=row11 and row16}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item \textbf{43\%} GHG reduction by 2030 (vs. 2019) for 1.5°C pathway
    \item Net zero CO₂ by ~2050 to limit warming to 1.5°C
    \item Remaining carbon budget from 2020: ~500 GtCO₂ (50\% likelihood)
  \end{itemize}
  \vspace{6pt}
  \colorbox{darkbg!60}{\parbox{0.92\linewidth}{%
    \fontsize{24}{32}\selectfont
    \textbf{Key levers}: rapid decarbonization, electrification of transport, demand efficiency, carbon sink protection.}}
}

\posterbox[ambercard, title={Scenario Comparison}
]{name=scenario, column=2, between=row11 and row16}{
  \fontsize{28}{36}\selectfont
  \centering
  \begin{tabular}{lcc}
    \rowcolor{secondary!15}
    \textbf{Target} & \textbf{2030 Cut} & \textbf{Net Zero CO₂} \\
    1.5°C & \color{059669}\bfseries 43\% & ~2050 \\
    2.0°C & 27\% & ~2070 \\
  \end{tabular}
  \vspace{8pt}
  \colorbox{yellowbg!60}{\parbox{0.92\linewidth}{%
    \fontsize{24}{32}\selectfont Delayed action increases costs, locks in high-carbon infrastructure, reduces feasibility.}}
}

\posterbox[highlightcard, title={The Narrowing Window for Action}
]{name=action, column=3, between=row11 and row16}{
  \fontsize{30}{40}\selectfont\color{white}
  \begin{itemize}[itemsep=10pt, itemcolor=white]
    \item Choices made \textbf{this decade} determine warming trajectory
    \item Climate finance falls short by factor of \textbf{3–6×} for adaptation
    \item Immediate, deep, sustained action across all sectors is essential
  \end{itemize}
  \vspace{6pt}
  \colorbox{accent!30}{\parbox{0.92\linewidth}{%
    \fontsize{24}{32}\selectfont\color{white}
    \textbf{Urgency message}: The window is rapidly closing. Securing a livable future requires unprecedented cooperation now.}}
}

% ══ ROW C: Key Takeaways ══
\posterbox[bluecard, title={Key Takeaways}
]{name=takeaways1, column=1, span=2, between=row16 and row20}{
  \fontsize{30}{40}\selectfont
  \begin{tabular}{p{0.45\linewidth}p{0.45\linewidth}}
    \rowcolor{bluebg!40}
    \textbf{Climate change is unequivocal} & \textbf{Acceleration} \\
    Human-caused warming is affecting every region on Earth with widespread and intensifying consequences. & Observed changes are accelerating beyond projections in some domains. \\
    \rowcolor{bluebg!40}
    \textbf{Cascading risks} & \textbf{Mitigation feasibility} \\
    Climate hazards interact with poverty, inequality, and ecosystem loss. & 1.5°C pathway still achievable but requires unprecedented transitions. \\
  \end{tabular}
}

\posterbox[redcard, title={Critical Numbers}
]{name=takeaways2, column=3, between=row16 and row20}{
  \fontsize{28}{36}\selectfont
  \centering
  \colorbox{accent!20}{\parbox{0.88\linewidth}{%
    \centering\vspace{4pt}%
    {\fontsize{48}{58}\selectfont\bfseries\color{accent}43\%}\\[2pt]
    {\fontsize{22}{28}\selectfont\color{textdark}GHG reduction needed by 2030}\vspace{6pt}%
  }}
  \colorbox{redbg!50}{\parbox{0.88\linewidth}{%
    \centering\vspace{4pt}%
    {\fontsize{42}{52}\selectfont\bfseries\color{accent}3.3–3.6B}\\[2pt]
    {\fontsize{22}{28}\selectfont\color{textdark}people exposed to severe climate hazards}\vspace{6pt}%
  }}
  \colorbox{yellowbg!50}{\parbox{0.88\linewidth}{%
    \fontsize{22}{28}\selectfont Source: IPCC AR6 Synthesis Report, 2023}}
}

\end{tcbposter}
\end{document}

