% ── IPCC Climate Theme ──
\definecolor{primary}{HTML}{1E3A5F}      % deep navy
\definecolor{secondary}{HTML}{D97706}    % amber
\definecolor{accent}{HTML}{DC2626}       % vermilion/red
\definecolor{greencol}{HTML}{059669}     % green
\definecolor{bgposter}{HTML}{F1F5F9}     % cool slate background
\definecolor{redbg}{HTML}{FEF2F2}        % warm red tint
\definecolor{bluebg}{HTML}{EFF6FF}       % cool blue tint
\definecolor{darkbg}{HTML}{F0FDF4}      % green tint for solutions
\definecolor{yellowbg}{HTML}{FFFBEB}    % warm amber tint
\definecolor{redtitlebg}{HTML}{FEE2E2}
\definecolor{bluetitlebg}{HTML}{DBEAFE}
\definecolor{darktitlebg}{HTML}{DCFCE7}
\definecolor{yellowtitlebg}{HTML}{FEF3C7}
\definecolor{textdark}{HTML}{1F2937}
\definecolor{textgray}{HTML}{4B5563}
