  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{76}{92}\selectfont\bfseries Climate Change 2023}\\[10pt]
  {\fontsize{42}{52}\selectfont\bfseries IPCC AR6 Synthesis Report Key Findings}\\[8pt]
  {\fontsize{30}{38}\selectfont\color{white!80} Intergovernmental Panel on Climate Change | 2023}
}

% ══ STATS BANNER — 7 Headline Metrics ══
