    \rowcolor{bluebg!40}
    \textbf{Cascading risks} & \textbf{Mitigation feasibility} \\
    Climate hazards interact with poverty, inequality, and ecosystem loss. & 1.5C pathway still achievable but requires unprecedented transitions. \\
  \end{tabular}
}

\posterbox[redcard, title={Critical Numbers}
]{name=takeaways2, column=3, between=row16 and row20}{
  \fontsize{28}{36}\selectfont
  \centering
  \colorbox{accent!20}{\parbox{0.88\linewidth}{%
    \centering\vspace{4pt}%
    {\fontsize{48}{58}\selectfont\bfseries\color{accent}43\%}\\[2pt]
    {\fontsize{22}{28}\selectfont\color{textdark}GHG reduction needed by 2030}\vspace{6pt}%
  }}
  \colorbox{redbg!50}{\parbox{0.88\linewidth}{%
    \centering\vspace{4pt}%
    {\fontsize{42}{52}\selectfont\bfseries\color{accent}3.3-3.6B}\\[2pt]
    {\fontsize{22}{28}\selectfont\color{textdark}people exposed to severe climate hazards}\vspace{6pt}%
  }}
  \colorbox{yellowbg!50}{\parbox{0.88\linewidth}{%
    \fontsize{22}{28}\selectfont Source: IPCC AR6 Synthesis Report, 2023}}
}

\end{tcbposter}
\end{document}

