\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── IPCC Climate Theme ──
\definecolor{primary}{HTML}{1E3A5F}      % deep navy
\definecolor{secondary}{HTML}{D97706}    % amber
\definecolor{accent}{HTML}{DC2626}       % vermilion/red
\definecolor{greencol}{HTML}{059669}     % green
\definecolor{bgposter}{HTML}{F1F5F9}     % cool slate background
\definecolor{redbg}{HTML}{FEF2F2}        % warm red tint
\definecolor{bluebg}{HTML}{EFF6FF}       % cool blue tint
\definecolor{darkbg}{HTML}{F0FDF4}      % green tint for solutions
\definecolor{yellowbg}{HTML}{FFFBEB}    % warm amber tint
\definecolor{redtitlebg}{HTML}{FEE2E2}
\definecolor{bluetitlebg}{HTML}{DBEAFE}
\definecolor{darktitlebg}{HTML}{DCFCE7}
\definecolor{yellowtitlebg}{HTML}{FEF3C7}
\definecolor{textdark}{HTML}{1F2937}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{FFEDD5}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=4pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}\textbullet}}
\setlist[enumerate]{leftmargin=20pt, itemsep=4pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=redtitlebg,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=bluetitlebg,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=yellowbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=yellowtitlebg,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{greencol},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{greencol},
    coltitle=greencol, colbacktitle=darktitlebg,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=2pt, titlerule style={greencol!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=accent!18!white,
    borderline west={6pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=accent,
    toptitle=4pt, bottomtitle=4pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{76}{92}\selectfont\bfseries Climate Change 2023}\\[10pt]
  {\fontsize{42}{52}\selectfont\bfseries IPCC AR6 Synthesis Report Key Findings}\\[8pt]
  {\fontsize{30}{38}\selectfont\color{white!80} Intergovernmental Panel on Climate Change | 2023}
}

% ══ STATS BANNER — 7 Headline Metrics ══
\posterbox[
  enhanced, colback=primary!10!white, boxrule=0pt, arc=0pt,
  left=8pt, right=8pt, top=4pt, bottom=4pt,
  valign=center, borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \fcolorbox{secondary!40}{stathighlight}{\parbox{0.125\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{54}{66}\selectfont\bfseries\color{primary}1.1C}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textdark}Temp. Rise}\vspace{4pt}%
  }}\hfill
  \fcolorbox{secondary!40}{stathighlight}{\parbox{0.125\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{54}{66}\selectfont\bfseries\color{primary}410}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textdark}CO2 ppm}\vspace{4pt}%
  }}\hfill
  \fcolorbox{secondary!40}{stathighlight}{\parbox{0.125\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{54}{66}\selectfont\bfseries\color{primary}59}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textdark}GtCO2e/yr}\vspace{4pt}%
  }}\hfill
  \fcolorbox{accent!40}{stathighlight}{\parbox{0.125\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{54}{66}\selectfont\bfseries\color{accent}~500}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textdark}GtCO2 Budget}\vspace{4pt}%
  }}\hfill
